import { useEffect, useMemo, useRef, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { HeartPulse, FileText, Sparkles, Check, CheckCircle, X, LogOut, Users, AlertCircle, AlertTriangle, RefreshCw, CalendarDays } from "lucide-react";

type Row = Record<string, unknown>;
const CSS =
  "body{transition-timing-function:cubic-bezier(.22,1,.36,1)!important;animation-timing-function:cubic-bezier(.22,1,.36,1)!important}" +
  ".cl-root{-webkit-font-smoothing:antialiased}.cl-root h1,.cl-root h2,.cl-root h3{font-family:inherit}" +
  ".cl-root *{transition-timing-function:cubic-bezier(.22,1,.36,1)}" +
  ".cl-root ::selection{background:#CDEDE7;color:#0B2A26}" +
  ".cl-root :focus-visible{outline:2px solid #12A594;outline-offset:2px}" +
  ".cl-scroll{scrollbar-width:none}.cl-scroll::-webkit-scrollbar{display:none}";
const EASE = [0.22, 1, 0.36, 1] as const;
const DAY = 86400000;
const START = 8;
const HOURS = 10;
const WD = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const WDL = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MO = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const ST: Record<string, { label: string; chip: string; dot: string; card: string }> = {
  booked: { label: "Booked", chip: "bg-[#E8F0FC] text-[#24508F]", dot: "bg-[#3B6FC4]", card: "border-[#D5E2E0] bg-white" },
  checked_in: { label: "Waiting", chip: "bg-[#FFF1DC] text-[#7A4300]", dot: "bg-[#D98A1C]", card: "border-[#F1D9AE] bg-[#FFFAF0]" },
  completed: { label: "Seen", chip: "bg-[#E7F4EA] text-[#2F6B3A]", dot: "bg-[#3F8F4E]", card: "border-[#D9E9DC] bg-[#F6FBF7]" },
  cancelled: { label: "Cancelled", chip: "bg-[#F0F3F2] text-[#55615F]", dot: "bg-[#93A19F]", card: "border-dashed border-[#D5DDDC] bg-[#F7F9F9]" },
};
const TONES: [string, string][] = [["#E6F4F1", "#0A6B61"], ["#E8F0FC", "#24508F"], ["#FDF0E1", "#8A4F07"], ["#F0EBFC", "#5B3AA8"], ["#FCEBF4", "#92306B"], ["#EAF5E0", "#3B6A17"], ["#FDECEA", "#9E2F26"]];

const s = (v: unknown): string => (v === null || v === undefined ? "" : String(v));
const pad = (n: number) => String(n).padStart(2, "0");
const ms = (v: unknown) => {
  const t = Date.parse(s(v));
  return Number.isNaN(t) ? 0 : t;
};
const hm = (t: number) => {
  const d = new Date(t);
  return pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes());
};
const dayStart = (t: number) => t - (((t % DAY) + DAY) % DAY);
const dateLong = (t: number) => {
  const d = new Date(t);
  return WD[d.getUTCDay()] + " " + d.getUTCDate() + " " + MO[d.getUTCMonth()];
};
const dateFull = (t: number) => {
  const d = new Date(t);
  return WDL[d.getUTCDay()] + " " + d.getUTCDate() + " " + MONTHS[d.getUTCMonth()];
};
const initials = (n: string) => n.replace("Dr. ", "").split(" ").map((p) => p[0] || "").join("").slice(0, 2).toUpperCase();
const toneOf = (name: string): [string, string] => TONES[name.split("").reduce((a, c) => a + c.charCodeAt(0), 0) % TONES.length];

function Avatar({ src, name, className, text }: { src?: string; name: string; className: string; text?: string }) {
  const [bad, setBad] = useState(false);
  if (src && !bad && !/\.svg(\?|$)/i.test(src)) return <img src={src} alt="" onError={() => setBad(true)} className={className + " shrink-0 object-cover"} />;
  const [bg, fg] = toneOf(name);
  return <span aria-hidden="true" className={className + " flex shrink-0 items-center justify-center font-bold " + (text || "text-[13px]")} style={{ background: bg, color: fg }}>{initials(name)}</span>;
}

function patientFacts(info: string, now: number) {
  const parts = info.split("·").map((p) => p.trim());
  let age = "";
  let allergy = "";
  parts.forEach((p) => {
    const m = /^b\.\s*(\d{4})$/.exec(p);
    if (m) age = new Date(now || Date.UTC(2026, 9, 12)).getUTCFullYear() - Number(m[1]) + " yrs";
    else if (/allerg/i.test(p) && !/^no known/i.test(p)) allergy = p.replace(/\s*allergy$/i, "");
  });
  return { age, allergy };
}

function AiText({ text }: { text: string }) {
  const lines = text.replace(/\*\*/g, "").split("\n").map((l) => l.trim()).filter(Boolean);
  const blocks: { kind: "ul" | "watch" | "head" | "p"; items: string[] }[] = [];
  lines.forEach((l) => {
    const b = /^([-•*]|\d+[.)])\s+(.*)$/.exec(l);
    const last = blocks[blocks.length - 1];
    if (b) {
      if (last && last.kind === "ul") last.items.push(b[2]);
      else blocks.push({ kind: "ul", items: [b[2]] });
    } else if (/^watch:/i.test(l)) blocks.push({ kind: "watch", items: [l.replace(/^watch:\s*/i, "")] });
    else if (/^next steps:?$/i.test(l)) blocks.push({ kind: "head", items: ["Next steps"] });
    else blocks.push({ kind: "p", items: [l] });
  });
  return (
    <div className="space-y-2.5 text-[15px] leading-relaxed text-[#24433F]">
      {blocks.map((bl, i) =>
        bl.kind === "ul" ? (
          <ul key={i} className="space-y-1.5">{bl.items.map((b, j) => <li key={j} className="flex gap-2.5"><span className="mt-[9px] h-1.5 w-1.5 shrink-0 rounded-full bg-[#0B7C70]" /><span>{b}</span></li>)}</ul>
        ) : bl.kind === "watch" ? (
          <div key={i} className="flex gap-2.5 rounded-xl bg-[#FFF6E5] p-3 text-[#5E3D00]"><AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-[#8A5A00]" /><span><span className="font-bold">Watch:</span> {bl.items[0]}</span></div>
        ) : bl.kind === "head" ? (
          <div key={i} className="pt-1 font-bold text-[#10302C]">Next steps</div>
        ) : (
          <p key={i}>{bl.items[0]}</p>
        )
      )}
    </div>
  );
}

function Skeleton({ caption }: { caption: string }) {
  return (
    <div aria-live="polite">
      <div className="space-y-2">{[92, 78, 64].map((w) => <div key={w} className="h-3 animate-pulse rounded-full bg-[#D7EAE6]" style={{ width: w + "%" }} />)}</div>
      <div className="mt-3 text-[13px] text-[#4A6662]">{caption}</div>
    </div>
  );
}

const field = "w-full rounded-xl border border-[#CFDEDB] bg-white px-3.5 py-3 text-[15px] text-[#10302C] outline-none transition-[border-color,box-shadow] duration-150 placeholder:text-[#5F7B77] focus:border-[#0B7C70] focus:ring-4 focus:ring-[#12A594]/15";
const lbl = "mb-1.5 block text-[14px] font-bold text-[#24433F]";

function Detail({ a, appts, notes, app, now, onDone, onClose }: { a: Row; appts: Row[]; notes: Row[]; app?: AppHandle; now: number; onDone: (m: string) => void; onClose?: () => void }) {
  const reduce = useReducedMotion();
  const id = s(a.id);
  const [form, setForm] = useState({ summary: "", diagnosis: "", plan: "", follow_up: "" });
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [ai, setAi] = useState("");
  const [aiBusy, setAiBusy] = useState(false);
  const [aiFail, setAiFail] = useState(false);
  const [vs, setVs] = useState("");
  const [vsBusy, setVsBusy] = useState(false);
  const [vsFail, setVsFail] = useState(false);
  useEffect(() => {
    setForm({ summary: "", diagnosis: "", plan: "", follow_up: "" });
    setErr("");
    setAi("");
    setAiFail(false);
    setVs("");
    setVsFail(false);
  }, [id]);

  const status = s(a.status);
  const st = ST[status] || ST.booked;
  const own = notes.find((n) => s(n.appointment_id) === id);
  const history = appts.filter((x) => s(x.patient_id) === s(a.patient_id) && s(x.id) !== id && s(x.status) === "completed" && ms(x.starts_at) < ms(a.starts_at)).sort((x, y) => ms(y.starts_at) - ms(x.starts_at));
  const noteOf = (x: Row) => notes.find((n) => s(n.appointment_id) === s(x.id));
  const open = status === "booked" || status === "checked_in";
  const facts = patientFacts(s(a.patient_info), now);

  const complete = async () => {
    if (!app || busy) return;
    if (!form.summary.trim() || !form.diagnosis.trim()) {
      setErr("Add a summary and a diagnosis before completing the visit.");
      return;
    }
    setBusy(true);
    setErr("");
    try {
      await app.create("visit_note", { appointment_id: id, patient_id: s(a.patient_id), doctor_id: s(a.doctor_id), summary: form.summary.trim(), diagnosis: form.diagnosis.trim(), plan: form.plan.trim() || "No further plan.", follow_up: form.follow_up.trim() || null });
      await app.transition("appointment", id, "status", "completed");
      onDone("Visit completed. " + s(a.patient_name) + " has been told their notes are ready.");
    } catch (e) {
      setErr(e instanceof Error && e.message ? e.message : "The notes couldn't be saved. Please try again.");
    } finally {
      setBusy(false);
    }
  };

  const summarise = async () => {
    if (!app || aiBusy) return;
    setAiBusy(true);
    setAi("");
    setAiFail(false);
    const lines = history.map((x) => {
      const n = noteOf(x);
      return dateLong(ms(x.starts_at)) + " " + s(x.reason) + (n ? ": " + s(n.summary) + " Diagnosis: " + s(n.diagnosis) + ". Plan: " + s(n.plan) : "");
    });
    try {
      const r = await app.ai.ask("Patient: " + s(a.patient_name) + " (" + s(a.patient_info) + "). Today's reason: " + s(a.reason) + ".\nPrevious visits:\n" + (lines.join("\n") || "None on record."), { system: "You summarise a patient's history for their doctor in at most 4 short bullet points starting with '- ', then one line starting 'Watch:' for anything to follow up. Use only the facts given; never invent details. No headings, no bold.", maxTokens: 320 });
      if (!r.trim()) throw new Error("empty");
      setAi(r);
    } catch {
      setAiFail(true);
    } finally {
      setAiBusy(false);
    }
  };

  const noteSrc = own ? { summary: s(own.summary), diagnosis: s(own.diagnosis), plan: s(own.plan), follow_up: s(own.follow_up) } : form;
  const hasNotes = !!(noteSrc.summary.trim() || noteSrc.plan.trim());
  const visitSummary = async () => {
    if (!app || vsBusy || !hasNotes) return;
    setVsBusy(true);
    setVsFail(false);
    setVs("");
    try {
      const r = await app.ai.ask("Visit notes for " + s(a.patient_name) + " (reason: " + s(a.reason) + ")\nSummary: " + noteSrc.summary + "\nDiagnosis: " + noteSrc.diagnosis + "\nPlan: " + noteSrc.plan + "\nFollow-up: " + noteSrc.follow_up, { system: "You write a short, warm, plain-language visit summary for a patient from their doctor's visit notes: 2-3 sentences, then a line 'Next steps:' followed by up to 4 bullet points starting with '- '. Use ONLY facts in the notes. Never diagnose, never add medical advice, doses, causes or reassurance beyond what the notes say; if something is missing, leave it out. No other headings, no bold.", maxTokens: 300 });
      if (!r.trim()) throw new Error("empty");
      setVs(r);
    } catch {
      setVsFail(true);
    } finally {
      setVsBusy(false);
    }
  };

  const aiBtn = "inline-flex h-10 shrink-0 items-center gap-1.5 rounded-xl border border-[#9FD3CA] bg-white px-3.5 text-[14px] font-bold text-[#0A6B61] transition-colors duration-150 hover:bg-[#E6F4F1] disabled:cursor-not-allowed disabled:opacity-60";

  return (
    <div>
      <div className="flex items-start gap-4">
        <Avatar src={s(a.patient_photo)} name={s(a.patient_name)} className="h-14 w-14 rounded-2xl" text="text-[17px]" />
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-[20px] font-extrabold tracking-[-0.01em]">{s(a.patient_name)}</h2>
          <div className="mt-1 flex flex-wrap items-center gap-2 text-[14px] text-[#4A6662]">
            {facts.age && <span>{facts.age}</span>}
            {facts.allergy ? <span className="inline-flex h-6 items-center gap-1 rounded-full bg-[#FDEEEC] px-2.5 text-[12px] font-bold text-[#A1261B]"><AlertTriangle className="h-3.5 w-3.5" /> {facts.allergy} allergy</span> : <span>No known allergies</span>}
          </div>
        </div>
        {onClose && <button onClick={onClose} aria-label="Close" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-[#24433F] hover:bg-[#F3F8F7]"><X className="h-5 w-5" /></button>}
      </div>

      <dl className="mt-5 grid grid-cols-2 gap-x-4 gap-y-3 border-y border-[#EEF3F2] py-4 text-[15px]">
        <div><dt className="text-[13px] font-semibold text-[#557370]">When</dt><dd className="mt-0.5 font-bold tabular-nums">{dateLong(ms(a.starts_at))}, {hm(ms(a.starts_at))}–{hm(ms(a.ends_at))}</dd></div>
        <div><dt className="text-[13px] font-semibold text-[#557370]">Status</dt><dd className="mt-1"><span className={"inline-flex h-6 items-center rounded-full px-2.5 text-[12px] font-bold " + st.chip}>{st.label}</span></dd></div>
        <div className="col-span-2"><dt className="text-[13px] font-semibold text-[#557370]">Reason for visit</dt><dd className="mt-0.5 font-bold">{s(a.reason)}</dd></div>
      </dl>

      <section className="mt-5">
        <div className="flex items-center justify-between gap-3">
          <h3 className="text-[16px] font-bold">Earlier visits <span className="font-semibold text-[#557370] tabular-nums">({history.length})</span></h3>
          {history.length > 0 && (
            <button onClick={() => void summarise()} disabled={aiBusy} className={aiBtn}>
              <Sparkles className="h-4 w-4" /> {aiBusy ? "Summarising…" : ai ? "Summarise again" : "Summarise with AI"}
            </button>
          )}
        </div>
        <AnimatePresence initial={false}>
          {(aiBusy || ai || aiFail) && (
            <motion.div initial={reduce ? false : { opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} transition={{ duration: 0.22, ease: EASE }} className="overflow-hidden">
              <div className="mt-3 rounded-xl border border-[#CDE7E2] bg-[#F3FAF8] p-4">
                {aiBusy ? (
                  <Skeleton caption={"Reading " + history.length + (history.length === 1 ? " earlier visit…" : " earlier visits…")} />
                ) : aiFail ? (
                  <div className="flex items-start gap-3 text-[14px] text-[#24433F]">
                    <AlertCircle className="mt-0.5 h-4 w-4 shrink-0 text-[#8A5A00]" />
                    <div className="flex-1">The AI summary isn't available right now. The visits are listed below.</div>
                    <button onClick={() => void summarise()} className="inline-flex h-9 shrink-0 items-center gap-1.5 rounded-lg px-2.5 text-[14px] font-bold text-[#0A6B61] hover:bg-[#E6F4F1]"><RefreshCw className="h-4 w-4" /> Retry</button>
                  </div>
                ) : (
                  <>
                    <div className="mb-2 flex items-center gap-1.5 text-[13px] font-bold text-[#0A6B61]"><Sparkles className="h-4 w-4" /> AI summary</div>
                    <AiText text={ai} />
                    <div className="mt-3 text-[12px] text-[#557370]">Written from the notes below. Check before acting on it.</div>
                  </>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
        {history.length > 0 ? (
          <ul className="mt-3 divide-y divide-[#EEF3F2] rounded-xl border border-[#E1EBE9]">
            {history.map((x) => {
              const n = noteOf(x);
              return (
                <li key={s(x.id)} className="px-4 py-3">
                  <div className="flex items-baseline justify-between gap-3">
                    <span className="truncate text-[15px] font-bold">{s(x.reason)}</span>
                    <span className="shrink-0 text-[13px] text-[#557370] tabular-nums">{dateLong(ms(x.starts_at))}</span>
                  </div>
                  {n ? (
                    <>
                      <div className="mt-0.5 text-[14px] font-semibold text-[#0A6B61]">{s(n.diagnosis)}</div>
                      <div className="mt-0.5 text-[14px] leading-snug text-[#4A6662]">{s(n.summary)}</div>
                    </>
                  ) : (
                    <div className="mt-0.5 text-[14px] text-[#557370]">No notes recorded.</div>
                  )}
                </li>
              );
            })}
          </ul>
        ) : (
          <p className="mt-2 text-[15px] text-[#4A6662]">First visit at Clinicly. There are no earlier notes.</p>
        )}
      </section>

      {open && (
        <form className="mt-6 border-t border-[#EEF3F2] pt-5" onSubmit={(e) => { e.preventDefault(); void complete(); }}>
          <h3 className="flex items-center gap-2 text-[16px] font-bold"><FileText className="h-4 w-4 text-[#0B7C70]" /> Visit notes</h3>
          <p className="mt-0.5 text-[14px] text-[#4A6662]">The patient can read these in their history once you complete the visit.</p>
          <div className="mt-4 space-y-3.5">
            <div><label htmlFor="vn-summary" className={lbl}>Summary <span className="text-[#A1261B]">*</span></label><textarea id="vn-summary" rows={3} className={field} placeholder="What you found and discussed" value={form.summary} onChange={(e) => setForm({ ...form, summary: e.target.value })} /></div>
            <div><label htmlFor="vn-dx" className={lbl}>Diagnosis <span className="text-[#A1261B]">*</span></label><input id="vn-dx" className={field + " h-12 py-0"} value={form.diagnosis} onChange={(e) => setForm({ ...form, diagnosis: e.target.value })} /></div>
            <div><label htmlFor="vn-plan" className={lbl}>Plan and prescriptions</label><textarea id="vn-plan" rows={2} className={field} value={form.plan} onChange={(e) => setForm({ ...form, plan: e.target.value })} /></div>
            <div><label htmlFor="vn-fu" className={lbl}>Follow-up</label><input id="vn-fu" className={field + " h-12 py-0"} placeholder="e.g. 4 weeks" value={form.follow_up} onChange={(e) => setForm({ ...form, follow_up: e.target.value })} /></div>
          </div>
          <AnimatePresence>{err && <motion.div role="alert" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="mt-3 flex gap-2 rounded-xl bg-[#FDEEEC] px-3.5 py-3 text-[14px] font-semibold text-[#A1261B]"><AlertCircle className="mt-0.5 h-4 w-4 shrink-0" /> {err}</motion.div>}</AnimatePresence>
          <button type="submit" disabled={busy} className="mt-4 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#0B7C70] text-[15px] font-bold text-white transition-colors duration-150 hover:bg-[#096A60] active:scale-[0.99] disabled:opacity-80">
            <Check className="h-5 w-5" /> {busy ? "Saving…" : "Save notes and complete visit"}
          </button>
        </form>
      )}

      {status === "completed" && own && (
        <section className="mt-6 border-t border-[#EEF3F2] pt-5">
          <h3 className="flex items-center gap-2 text-[16px] font-bold text-[#2F6B3A]"><CheckCircle className="h-4 w-4" /> Notes for this visit</h3>
          <dl className="mt-2 divide-y divide-[#EEF3F2]">
            {[["Summary", s(own.summary)], ["Diagnosis", s(own.diagnosis)], ["Plan", s(own.plan)], ["Follow-up", s(own.follow_up)]].filter((r) => r[1]).map((r) => (
              <div key={r[0]} className="py-2.5"><dt className="text-[13px] font-semibold text-[#557370]">{r[0]}</dt><dd className="mt-0.5 text-[15px] leading-relaxed">{r[1]}</dd></div>
            ))}
          </dl>
        </section>
      )}

      {status !== "cancelled" && (
        <section className="mt-6 rounded-xl border border-[#CDE7E2] bg-[#F3FAF8] p-4">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h3 className="flex items-center gap-2 text-[16px] font-bold"><Sparkles className="h-4 w-4 text-[#0B7C70]" /> Summary for the patient</h3>
              <p className="mt-0.5 text-[14px] text-[#4A6662]">{hasNotes ? "Turn your notes into plain language for " + s(a.patient_name).split(" ")[0] + "." : "Write visit notes first, then draft a plain-language summary."}</p>
            </div>
            <button onClick={() => void visitSummary()} disabled={vsBusy || !hasNotes} className={aiBtn}>{vsBusy ? "Writing…" : vs ? "Rewrite" : "Draft"}</button>
          </div>
          {vsBusy && <div className="mt-4"><Skeleton caption="Drafting from your notes…" /></div>}
          {vsFail && !vsBusy && <div className="mt-3 flex items-center gap-2 text-[14px] text-[#5E3D00]"><AlertCircle className="h-4 w-4 shrink-0" /> The AI draft isn't available right now. Try again in a moment.</div>}
          {vs && !vsBusy && (
            <div className="mt-4 rounded-xl bg-white p-4">
              <div className="mb-2 text-[13px] font-bold text-[#7A4300]">Draft. Review before sharing.</div>
              <AiText text={vs} />
            </div>
          )}
        </section>
      )}
    </div>
  );
}

export default function DoctorApp({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const appRef = useRef(app);
  appRef.current = app;
  const [now, setNow] = useState(0);
  const [off, setOff] = useState(0);
  const [selId, setSelId] = useState("");
  const [wide, setWide] = useState(false);
  const [toast, setToast] = useState("");
  const [pickDoc, setPickDoc] = useState("");
  const [H, setH] = useState(72);

  useEffect(() => {
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 20000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    const mq = window.matchMedia("(min-width: 1024px)");
    const f = () => {
      setWide(mq.matches);
      setH(mq.matches ? 84 : 72);
    };
    f();
    mq.addEventListener("change", f);
    return () => mq.removeEventListener("change", f);
  }, []);
  useEffect(() => {
    const a = appRef.current;
    if (!a) return;
    const offs = ["appointment", "visit_note"].map((e) => a.live(e));
    return () => offs.forEach((o) => o());
  }, []);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 4500);
    return () => clearTimeout(t);
  }, [toast]);

  const allAppts = (app?.rows("appointment") || []) as Row[];
  const notes = (app?.rows("visit_note") || []) as Row[];
  const doctors = (app?.rows("doctor") || []) as Row[];
  const meId = app?.me("doctor") || "";
  const meRow = doctors.find((d) => s(d.id) === meId);
  const today = now ? dayStart(now) : dayStart(Date.UTC(2026, 9, 12));
  const docsWithAppts = useMemo(() => {
    const c: Record<string, number> = {};
    allAppts.forEach((a) => {
      if (dayStart(ms(a.starts_at)) === today) c[s(a.doctor_id)] = (c[s(a.doctor_id)] || 0) + 1;
    });
    return c;
  }, [allAppts, today]);
  const fallbackDoc = Object.keys(docsWithAppts).sort((x, y) => docsWithAppts[y] - docsWithAppts[x])[0] || s(doctors[0]?.id);
  const viewDoc = meId || pickDoc || fallbackDoc;
  const viewRow = doctors.find((d) => s(d.id) === viewDoc);
  const appts = meId ? allAppts : allAppts.filter((a) => s(a.doctor_id) === viewDoc);
  const displayName = s(meRow?.name || app?.user.name) || "Doctor";
  const lastName = s(meRow?.name).replace("Dr. ", "").split(" ").slice(-1)[0];
  const hour = now ? new Date(now).getUTCHours() : 9;
  const greet = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";

  const base = today + off * DAY;
  const days = [-1, 0, 1, 2, 3, 4, 5].map((i) => today + i * DAY);
  const dayAppts = useMemo(() => appts.filter((a) => dayStart(ms(a.starts_at)) === base).sort((a, b) => ms(a.starts_at) - ms(b.starts_at)), [appts, base]);
  const active = dayAppts.filter((a) => s(a.status) !== "cancelled");
  const counts = (d: number) => appts.filter((a) => dayStart(ms(a.starts_at)) === d && s(a.status) !== "cancelled").length;
  const done = active.filter((a) => s(a.status) === "completed").length;
  const waiting = active.filter((a) => s(a.status) === "checked_in").length;
  const toCome = active.filter((a) => s(a.status) === "booked").length;
  const nextUp = active.find((a) => s(a.status) !== "completed" && ms(a.ends_at) > now);
  const sel = allAppts.find((a) => s(a.id) === selId);
  const isToday = off === 0;
  const nowTop = now ? ((now - today) / 3600000 - START) * H : -1;
  const showNow = isToday && nowTop >= 0 && nowTop <= HOURS * H;
  const loading = !!app?.loading("appointment") && allAppts.length === 0;
  const card = "rounded-2xl border border-[#E1EBE9] bg-white";
  const pct = active.length ? Math.round((done / active.length) * 100) : 0;
  const unlinked = !meId && !loading && !!now && allAppts.length === 0;

  return (
    <div className="cl-root min-h-[100dvh] w-full bg-[#F6FAF9] text-[#10302C]">
      <style>{CSS}</style>
      <header className="sticky top-0 z-30 border-b border-[#E1EBE9] bg-white/95 backdrop-blur">
        <div className="mx-auto flex h-16 max-w-7xl items-center justify-between gap-3 px-4 lg:px-8">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2.5">
              <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#0B7C70] text-white"><HeartPulse className="h-5 w-5" /></span>
              <span className="text-[18px] font-extrabold tracking-[-0.01em]">Clinicly</span>
            </div>
            <nav aria-label="Main" className="hidden items-center gap-1 sm:flex">
              <span aria-current="page" className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#E6F4F1] px-3 text-[14px] font-bold text-[#0A6B61]"><CalendarDays className="h-4 w-4" /> My day</span>
              <a href="/team" onClick={(e) => { if (app) { e.preventDefault(); app.navigate("/team"); } }} className="inline-flex h-10 items-center gap-2 rounded-xl px-3 text-[14px] font-bold text-[#4A6662] no-underline transition-colors duration-150 hover:bg-[#F3F8F7] hover:text-[#10302C]"><Users className="h-4 w-4" /> Team &amp; access</a>
            </nav>
          </div>
          <div className="flex items-center gap-2">
            <a href="/team" aria-label="Team and access" onClick={(e) => { if (app) { e.preventDefault(); app.navigate("/team"); } }} className="flex h-11 w-11 items-center justify-center rounded-full text-[#24433F] hover:bg-[#F3F8F7] sm:hidden"><Users className="h-5 w-5" /></a>
            <div className="hidden text-right md:block">
              <div className="text-[14px] font-bold leading-tight">{displayName}</div>
              <div className="text-[13px] text-[#557370]">{meRow ? s(meRow.specialty) + " · " + s(meRow.room) : "Clinic admin"}</div>
            </div>
            <Avatar src={s(meRow?.photo)} name={displayName} className="h-9 w-9 rounded-full" />
            <button onClick={() => void app?.auth.signOut()} aria-label="Sign out" title="Sign out" className="flex h-11 w-11 items-center justify-center rounded-full text-[#4A6662] transition-colors duration-150 hover:bg-[#F3F8F7] hover:text-[#10302C]"><LogOut className="h-5 w-5" /></button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 pb-16 pt-6 lg:px-8 lg:pt-8">
        <h1 className="text-[26px] font-extrabold leading-tight tracking-[-0.02em] lg:text-[32px]">{meRow ? greet + ", Dr. " + lastName : unlinked ? greet + ", " + displayName.split(" ")[0] : isToday ? "Clinic day" : dateFull(base)}</h1>
        <p className="mt-1 text-[16px] text-[#4A6662]">
          {dateFull(base)}{meRow || unlinked ? "" : viewRow ? " · " + s(viewRow.name) : ""}
          {nextUp && isToday ? <> · Next: <span className="font-semibold text-[#10302C]">{s(nextUp.patient_name)} at <span className="tabular-nums">{hm(ms(nextUp.starts_at))}</span></span></> : null}
        </p>

        {unlinked ? (
          <section className={card + " mt-6 max-w-2xl p-6 sm:p-8"}>
            <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#E6F4F1] text-[#0B7C70]"><Users className="h-6 w-6" /></span>
            <h2 className="mt-4 text-[20px] font-bold">This account isn't linked to a doctor yet</h2>
            <p className="mt-1.5 max-w-[56ch] text-[15px] leading-relaxed text-[#4A6662]">Doctors only see their own patients, so there is no timeline to show here. Link this person to a doctor profile, or sign in as Dr. Amara Okafor or Dr. Daniel Reyes to try a full clinic day with notes and AI summaries.</p>
            <button onClick={() => app?.navigate("/team")} className="mt-5 inline-flex h-11 items-center gap-2 rounded-xl bg-[#0B7C70] px-5 text-[15px] font-bold text-white hover:bg-[#096A60]"><Users className="h-4 w-4" /> Open Team &amp; access</button>
          </section>
        ) : (<>
        {!meId && doctors.length > 0 && (
          <div className="cl-scroll -mx-4 mt-4 overflow-x-auto px-4 lg:mx-0 lg:px-0">
            <div role="group" aria-label="Choose a doctor" className="flex w-max gap-2">
              {doctors.slice().sort((x, y) => s(x.name).localeCompare(s(y.name))).map((d) => {
                const on = s(d.id) === viewDoc;
                return <button key={s(d.id)} aria-pressed={on} onClick={() => { setPickDoc(s(d.id)); setSelId(""); }} className={"h-11 shrink-0 rounded-full px-4 text-[14px] font-bold transition-colors duration-150 " + (on ? "bg-[#0B7C70] text-white" : "border border-[#CFDEDB] bg-white text-[#24433F] hover:border-[#B5CCC8]")}>{s(d.name)}</button>;
              })}
            </div>
          </div>
        )}

        <section aria-label="Day progress" className={card + " mt-5 p-4 sm:p-5"}>
          <div className="grid grid-cols-2 gap-y-4 sm:grid-cols-4 sm:divide-x sm:divide-[#EEF3F2]">
            {[{ l: "Patients", v: active.length }, { l: "Seen", v: done }, { l: "In the waiting room", v: waiting }, { l: "Still to come", v: toCome }].map((c, i) => (
              <div key={c.l} className={i > 0 ? "sm:pl-5" : ""}>
                <div className="text-[28px] font-extrabold leading-none tabular-nums">{loading ? "–" : c.v}</div>
                <div className="mt-1.5 text-[14px] text-[#4A6662]">{c.l}</div>
              </div>
            ))}
          </div>
          <div className="mt-4 h-2 overflow-hidden rounded-full bg-[#EEF3F2]" role="progressbar" aria-label="Patients seen" aria-valuenow={pct} aria-valuemin={0} aria-valuemax={100}>
            <motion.div className="h-full rounded-full bg-[#12A594]" initial={reduce ? false : { width: 0 }} animate={{ width: pct + "%" }} transition={{ duration: 0.5, ease: EASE }} />
          </div>
        </section>

