export default function ClinicLogin({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const auth = app?.auth;
  const [localMode, setLocalMode] = useState<"in" | "up">("in");
  const rawMode = auth ? (auth as { mode?: string }).mode : undefined;
  const mode: "in" | "up" = rawMode === "up" || rawMode === "signUp" || rawMode === "signup" ? "up" : rawMode ? "in" : localMode;
  const canSignUp = auth ? (auth as { canSignUp?: boolean }).canSignUp !== false : true;
  const providers = ((auth as { providers?: { name: string; label: string }[] } | undefined)?.providers || []) as { name: string; label: string }[];
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const flip = () => {
    setErr("");
    const next = mode === "in" ? "up" : "in";
    setLocalMode(next);
    const sm = (auth as { setMode?: (m: string) => void } | undefined)?.setMode;
    if (sm) sm(next);
  };

  const submit = async () => {
    if (!auth || busy) return;
    if (!email.trim() || !password) {
      setErr("Enter your email and password to continue.");
      return;
    }
    setBusy(true);
    setErr("");
    try {
      if (mode === "in") await auth.signIn(email.trim(), password);
      else await auth.signUp({ name: name.trim() || email.split("@")[0], email: email.trim(), password });
    } catch (e) {
      setErr(e instanceof Error && e.message ? e.message : "We couldn't sign you in. Check your email and password and try again.");
    } finally {
      setBusy(false);
    }
  };

  const provider = async (p: string) => {
    setErr("");
    try {
      const sp = (auth as { startProvider?: (n: string) => Promise<unknown> } | undefined)?.startProvider;
      if (sp) await sp(p);
    } catch (e) {
      setErr(e instanceof Error && e.message ? e.message : "That sign-in didn't start. Please try again.");
    }
  };

  const inputCls =
    "h-12 w-full rounded-xl border border-[#CFDEDB] bg-white px-4 text-[16px] text-[#10302C] outline-none transition-[border-color,box-shadow] duration-150 placeholder:text-[#5F7B77] hover:border-[#B5CCC8] focus:border-[#0B7C70] focus:ring-4 focus:ring-[#12A594]/15";
  const enter = (d: number) => (reduce ? {} : { initial: { opacity: 0, y: 8 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.35, ease: EASE, delay: d } });

  return (
