      <div className="mx-auto grid min-h-[100dvh] max-w-6xl items-center gap-10 px-4 py-8 sm:px-6 lg:grid-cols-[1fr_440px] lg:gap-20 lg:px-10">
        <div className="order-2 lg:order-1">
          <div className="hidden items-center gap-3 lg:flex">
            <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#0B7C70] text-white"><HeartPulse className="h-6 w-6" strokeWidth={2} /></span>
            <span className="text-[22px] font-extrabold tracking-[-0.01em]">Clinicly</span>
          </div>
          <p className="mt-10 hidden max-w-[16ch] text-[44px] font-extrabold leading-[1.08] tracking-[-0.025em] text-[#10302C] lg:block">Care that fits your day.</p>
          <p className="mt-4 hidden max-w-[42ch] text-[17px] leading-relaxed text-[#4A6662] lg:block">Book a visit with a doctor you trust, arrive prepared, and keep your visit notes in one calm place.</p>
          <ul className="grid gap-4 sm:grid-cols-3 lg:mt-10 lg:grid-cols-1 lg:gap-5">
            {FACTS.map((f) => (
              <li key={f.t} className="flex gap-3.5">
