        </div>

        <motion.div {...enter(0)} className="order-1 w-full lg:order-2">
          <div className="mb-6 flex items-center justify-center gap-2.5 lg:hidden">
            <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#0B7C70] text-white"><HeartPulse className="h-5 w-5" strokeWidth={2} /></span>
