            <form className="mt-6 space-y-4" onSubmit={(e) => { e.preventDefault(); void submit(); }} noValidate>
              <AnimatePresence initial={false}>
                {mode === "up" && (
                  <motion.div key="name" initial={reduce ? false : { opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} transition={{ duration: 0.2, ease: EASE }} className="overflow-hidden">
