                    <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" /> {err}
                  </motion.div>
                )}
              </AnimatePresence>

              <button type="submit" disabled={busy} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#0B7C70] text-[16px] font-bold text-white transition-colors duration-150 hover:bg-[#096A60] active:scale-[0.99] disabled:cursor-wait disabled:opacity-80">
                {busy && <RefreshCw className="h-4 w-4 animate-spin" />}
                {mode === "in" ? (busy ? "Signing in…" : "Sign in") : busy ? "Creating account…" : "Create account"}
