            {providers.length > 0 && (
              <div className="mt-5">
                <div className="mb-5 flex items-center gap-3 text-[13px] font-semibold text-[#557370]">
                  <span className="h-px flex-1 bg-[#E1EBE9]" /> or <span className="h-px flex-1 bg-[#E1EBE9]" />
                </div>
                <div className="space-y-2.5">
                  {providers.map((p) => (
                    <button key={p.name} type="button" onClick={() => void provider(p.name)} className="flex h-12 w-full items-center justify-center gap-3 rounded-xl border border-[#CFDEDB] bg-white text-[15px] font-bold text-[#10302C] transition-colors duration-150 hover:bg-[#F3F8F7]">
                      {p.name === "google" && <GoogleG />}
                      Continue with {p.label}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {(canSignUp || mode === "up") && (
              <p className="mt-6 text-center text-[15px] text-[#4A6662]">
                {mode === "in" ? "New to Clinicly? " : "Already have an account? "}
                <button type="button" className="inline-flex min-h-[44px] items-center font-bold text-[#0A6E63] underline decoration-[#0A6E63]/30 underline-offset-4 hover:decoration-[#0A6E63]" onClick={flip}>
                  {mode === "in" ? "Create an account" : "Sign in instead"}
                </button>
              </p>
            )}
          </div>
          <p className="mt-4 text-center text-[14px] text-[#4A6662]">Doctors and front-desk staff get their sign-in from the clinic.</p>
        </motion.div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Star, Clock, ChevronLeft, ChevronRight, Check, Lightbulb, MapPin, AlertCircle, Calendar, Search } from "lucide-react";

type Row = Record<string, unknown>;
const CSS =
  "body{transition-timing-function:cubic-bezier(.22,1,.36,1)!important;animation-timing-function:cubic-bezier(.22,1,.36,1)!important}" +
  ".cl-root{-webkit-font-smoothing:antialiased}.cl-root h1,.cl-root h2,.cl-root h3{font-family:inherit}" +
  ".cl-root *{transition-timing-function:cubic-bezier(.22,1,.36,1)}" +
  ".cl-root ::selection{background:#CDEDE7;color:#0B2A26}" +
  ".cl-root :focus-visible{outline:2px solid #12A594;outline-offset:2px}";
const EASE = [0.22, 1, 0.36, 1] as const;
const DUR = 30 * 60000;
const DAY = 86400000;
const WD = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MO = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const PREP: Record<string, string> = {
  "General Practice": "Bring your insurance card and a list of current medications.",
  Cardiology: "Avoid caffeine for 4 hours before and bring any recent ECG results.",
  Dermatology: "Come with clean skin, no makeup on the area we will look at.",
  Pediatrics: "Bring the vaccination card. A parent or guardian should attend.",
  Neurology: "Keep a short symptom diary and bring a list of medications.",
  Orthopedics: "Wear loose clothing and bring any previous scans or X-rays.",
  "Mental Health": "No preparation needed. Arrive a few minutes early to settle in.",
};
const REASONS = ["Check-up", "Follow-up", "New symptoms", "Test results", "Prescription"];
const TONES: [string, string][] = [["#E6F4F1", "#0A6B61"], ["#E8F0FC", "#24508F"], ["#FDF0E1", "#8A4F07"], ["#F0EBFC", "#5B3AA8"], ["#FCEBF4", "#92306B"], ["#EAF5E0", "#3B6A17"], ["#FDECEA", "#9E2F26"]];
const SPEC: Record<string, number> = { "General Practice": 0, Pediatrics: 1, Dermatology: 2, Neurology: 3, "Mental Health": 4, Orthopedics: 5, Cardiology: 6 };

const s = (v: unknown): string => (v === null || v === undefined ? "" : String(v));
const pad = (n: number) => String(n).padStart(2, "0");
const ms = (v: unknown) => {
  const t = Date.parse(s(v));
  return Number.isNaN(t) ? 0 : t;
};
const hm = (t: number) => {
  const d = new Date(t);
  return pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes());
};
const dayStart = (t: number) => t - (((t % DAY) + DAY) % DAY);
const dateLong = (t: number) => {
  const d = new Date(t);
  return WD[d.getUTCDay()] + " " + d.getUTCDate() + " " + MO[d.getUTCMonth()];
};
const rel = (t: number, now: number) => {
  const d = Math.round((dayStart(t) - dayStart(now)) / DAY);
  if (d === 0) return "Today";
  if (d === 1) return "Tomorrow";
  return dateLong(t);
};
const initials = (n: string) => n.replace("Dr. ", "").split(" ").map((p) => p[0] || "").join("").slice(0, 2).toUpperCase();
const tone = (spec: string): [string, string] => TONES[SPEC[spec] !== undefined ? SPEC[spec] : 0];

function Avatar({ src, name, spec, className, text }: { src?: string; name: string; spec: string; className: string; text: string }) {
  const [bad, setBad] = useState(false);
  if (src && !bad && !/\.svg(\?|$)/i.test(src)) return <img src={src} alt="" onError={() => setBad(true)} className={className + " shrink-0 object-cover"} />;
  const [bg, fg] = tone(spec);
  return <span aria-hidden="true" className={className + " flex shrink-0 items-center justify-center font-bold " + text} style={{ background: bg, color: fg }}>{initials(name)}</span>;
}

export default function BookDoctor({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const appRef = useRef(app);
  appRef.current = app;
  const [now, setNow] = useState(0);
  const [week, setWeek] = useState(0);
  const [day, setDay] = useState(-1);
  const [slot, setSlot] = useState(0);
  const [reason, setReason] = useState("Check-up");
  const [custom, setCustom] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [done, setDone] = useState(0);
  const [mine, setMine] = useState<number[]>([]);

  useEffect(() => {
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    const a = appRef.current;
    if (!a) return;
    const offs = ["slot", "appointment"].map((e) => a.live(e));
    return () => offs.forEach((o) => o());
  }, []);

  const id = s(app?.params.id);
  const doctors = (app?.rows("doctor") || []) as Row[];
  const doctor = doctors.find((d) => s(d.id) === id);
  const loading = !!app?.loading("doctor") && doctors.length === 0;
  const slots = (app?.rows("slot") || []) as Row[];
  const me = ((app?.rows("patient") || []) as Row[])[0];
  const spec = s(doctor?.specialty);

  const busyList = useMemo(() => {
    const l: { s: number; e: number }[] = [];
    slots.forEach((r) => {
      if (r.active !== false && s(r.doctor_id) === id) l.push({ s: ms(r.starts_at), e: ms(r.ends_at) });
    });
    mine.forEach((m) => l.push({ s: m, e: m + DUR }));
    return l;
  }, [slots, mine, id]);

  const isFree = (t: number) => !!now && t > now + 15 * 60000 && !busyList.some((b) => b.s < t + DUR && b.e > t);
  const base = now ? dayStart(now) : dayStart(Date.UTC(2026, 9, 12));
  const days = [0, 1, 2, 3, 4, 5, 6].map((i) => base + (week * 7 + i) * DAY);
  const dayTimes = (d: number) => {
    const out: number[] = [];
    for (let m = 480; m < 1080; m += 30) out.push(d + m * 60000);
    return out;
  };
  const freeCount = days.map((d) => dayTimes(d).filter(isFree).length);
  const firstOpen = freeCount.findIndex((c) => c > 0);
  const dayIdx = day >= 0 ? day : firstOpen >= 0 ? firstOpen : 0;
  const selDay = days[dayIdx];
  const free = dayTimes(selDay).filter(isFree);
  const groups: [string, number[]][] = [
    ["Morning", free.filter((t) => new Date(t).getUTCHours() < 12)],
    ["Afternoon", free.filter((t) => new Date(t).getUTCHours() >= 12)],
  ];
  const dm = new Date(days[0]);
  const dmEnd = new Date(days[6]);
  const monthLabel = dm.getUTCMonth() === dmEnd.getUTCMonth() ? MONTHS[dm.getUTCMonth()] + " " + dm.getUTCFullYear() : MO[dm.getUTCMonth()] + " – " + MO[dmEnd.getUTCMonth()] + " " + dmEnd.getUTCFullYear();
  const finalReason = custom.trim() || reason;

  const changeWeek = (w: number) => {
    setWeek(w);
    setDay(-1);
    setSlot(0);
  };

  const confirm = async () => {
    const a = appRef.current;
    if (!a || !slot || busy || !doctor) return;
    setBusy(true);
    setErr("");
    const born = s(me?.dob).slice(0, 4);
    try {
      await a.create("appointment", {
        patient_id: a.me("patient"),
        doctor_id: id,
        patient_name: s(me?.name || a.user.name),
        patient_photo: s(me?.photo) || null,
        patient_info: (born ? "b. " + born + " · " : "") + (s(me?.allergies) && s(me?.allergies) !== "None known" ? s(me?.allergies) + " allergy" : "No known allergies"),
        doctor_name: s(doctor.name),
        starts_at: new Date(slot).toISOString(),
        ends_at: new Date(slot + DUR).toISOString(),
        reason: finalReason,
        status: "booked",
        prep_notes: PREP[spec] || "Arrive 10 minutes early to check in.",
      });
      setMine((m) => m.concat([slot]));
      setDone(slot);
    } catch (e) {
      setErr(e instanceof Error && e.message ? e.message : "That time couldn't be booked. Please pick another.");
    } finally {
      setBusy(false);
    }
  };

  const card = "rounded-2xl border border-[#E1EBE9] bg-white";
  const enter = (d: number) => (reduce ? {} : { initial: { opacity: 0, y: 8 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.28, ease: EASE, delay: d } });
  const iconBtn = "flex h-11 w-11 items-center justify-center rounded-full border border-[#CFDEDB] bg-white text-[#24433F] transition-colors duration-150 hover:bg-[#F3F8F7] disabled:cursor-not-allowed disabled:opacity-40";

  return (
    <div className="cl-root min-h-[100dvh] w-full bg-[#F6FAF9] text-[#10302C]">
      <style>{CSS}</style>
      <header className="sticky top-0 z-20 border-b border-[#E1EBE9] bg-white/95 backdrop-blur">
        <div className="mx-auto flex h-16 max-w-5xl items-center gap-2 px-2 sm:px-4 lg:px-8">
          <button aria-label="Back to doctors" onClick={() => app?.navigate("/book")} className="flex h-11 w-11 items-center justify-center rounded-full text-[#24433F] transition-colors duration-150 hover:bg-[#F3F8F7]">
            <ChevronLeft className="h-6 w-6" />
          </button>
          <div className="text-[17px] font-bold">Book a visit</div>
        </div>
      </header>

      <main className="mx-auto grid max-w-5xl items-start gap-4 px-4 pb-16 pt-5 lg:grid-cols-[340px_1fr] lg:gap-8 lg:px-8 lg:pt-8">
        {!doctor ? (
          loading || !now ? (
            <>
              <div className={card + " h-64 animate-pulse bg-[#EEF4F3]"} />
              <div className={card + " h-96 animate-pulse bg-[#EEF4F3]"} />
            </>
          ) : (
            <div className={card + " col-span-full px-6 py-14 text-center"}>
              <span className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#E6F4F1] text-[#0B7C70]"><Search className="h-6 w-6" /></span>
              <h1 className="mt-4 text-[19px] font-bold">We couldn't find this doctor</h1>
              <p className="mx-auto mt-1 max-w-[40ch] text-[15px] text-[#4A6662]">They may no longer take bookings. Choose another doctor from the list.</p>
              <button onClick={() => app?.navigate("/book")} className="mt-5 inline-flex h-11 items-center rounded-xl bg-[#0B7C70] px-5 text-[15px] font-bold text-white hover:bg-[#096A60]">See all doctors</button>
            </div>
          )
        ) : (
          <>
            <motion.aside {...enter(0)} className={card + " p-5 lg:sticky lg:top-24"}>
              <div className="flex items-center gap-4">
                <Avatar src={s(doctor.photo)} name={s(doctor.name)} spec={spec} className="h-16 w-16 rounded-2xl" text="text-[20px]" />
                <div className="min-w-0">
                  <h1 className="text-[21px] font-extrabold leading-tight tracking-[-0.01em]">{s(doctor.name)}</h1>
                  <div className="text-[15px] font-semibold" style={{ color: tone(spec)[1] }}>{spec}</div>
                </div>
              </div>
              <div className="mt-4 flex flex-wrap gap-x-4 gap-y-1.5 text-[14px] text-[#4A6662]">
                <span className="inline-flex items-center gap-1.5"><Star className="h-4 w-4 fill-[#E7A631] text-[#E7A631]" /><span className="font-bold text-[#10302C] tabular-nums">{Number(doctor.rating).toFixed(1)}</span><span className="tabular-nums">({s(doctor.review_count)} reviews)</span></span>
                <span>{s(doctor.years_experience)} years in practice</span>
                <span className="inline-flex items-center gap-1.5"><MapPin className="h-4 w-4" />{s(doctor.room)}</span>
              </div>
              <p className="mt-4 text-[15px] leading-relaxed text-[#24433F]">{s(doctor.bio)}</p>
              <div className="mt-4 flex gap-3 rounded-xl bg-[#FFF6E5] p-3.5">
                <Lightbulb className="mt-0.5 h-4 w-4 shrink-0 text-[#8A5A00]" />
                <p className="text-[14px] leading-snug text-[#5E3D00]"><span className="font-bold">Before you come:</span> {PREP[spec] || "Arrive 10 minutes early to check in."}</p>
              </div>
            </motion.aside>

            <motion.section {...enter(0.05)} className={card + " p-5 lg:p-7"}>
              <AnimatePresence mode="wait" initial={false}>
                {done ? (
                  <motion.div key="done" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.25, ease: EASE }} className="py-8 text-center" role="status">
                    <div className="mx-auto flex h-20 w-20 items-center justify-center rounded-full bg-[#E6F4F1]">
                      <svg viewBox="0 0 24 24" className="h-10 w-10 text-[#0B7C70]" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                        <motion.path d="M5 12.5l4.5 4.5L19 7.5" initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ delay: 0.1, duration: 0.4, ease: EASE }} />
                      </svg>
                    </div>
                    <h2 className="mt-5 text-[24px] font-extrabold tracking-[-0.015em]">You're booked</h2>
                    <p className="mt-2 text-[16px] text-[#24433F]"><span className="font-bold">{rel(done, now)}, {dateLong(done)} at <span className="tabular-nums">{hm(done)}</span></span> with {s(doctor.name)}</p>
                    <p className="mt-1 text-[15px] text-[#4A6662]">{s(doctor.room)} · 30 minutes · We'll remind you the day before.</p>
                    <div className="mt-7 flex flex-col justify-center gap-3 sm:flex-row">
                      <button onClick={() => app?.navigate("/visits")} className="inline-flex h-12 items-center justify-center rounded-xl bg-[#0B7C70] px-6 text-[15px] font-bold text-white hover:bg-[#096A60]">See my visits</button>
                      <button onClick={() => app?.navigate("/book")} className="inline-flex h-12 items-center justify-center rounded-xl border border-[#CFDEDB] bg-white px-6 text-[15px] font-bold text-[#10302C] hover:bg-[#F3F8F7]">Back to doctors</button>
                    </div>
                  </motion.div>
                ) : (
                  <motion.div key="form" initial={false} animate={{ opacity: 1 }}>
                    <div className="flex items-center justify-between gap-3">
                      <div>
                        <h2 className="text-[19px] font-bold">Choose a day</h2>
                        <div className="text-[14px] text-[#4A6662]">{monthLabel}<span className="hidden sm:inline"> · open 08:00–18:00</span></div>
                      </div>
                      <div className="flex gap-2">
                        <button aria-label="Previous week" disabled={week === 0} onClick={() => changeWeek(week - 1)} className={iconBtn}><ChevronLeft className="h-5 w-5" /></button>
                        <button aria-label="Next week" disabled={week >= 3} onClick={() => changeWeek(week + 1)} className={iconBtn}><ChevronRight className="h-5 w-5" /></button>
                      </div>
                    </div>
                    <div role="radiogroup" aria-label="Day" className="mt-4 grid grid-cols-7 gap-1.5 sm:gap-2">
                      {days.map((d, i) => {
                        const fc = freeCount[i];
                        const on = dayIdx === i;
                        const off = Math.round((d - base) / DAY);
                        return (
                          <button key={d} role="radio" aria-checked={on} aria-label={dateLong(d) + ", " + (fc ? fc + " free times" : "fully booked")} disabled={fc === 0} onClick={() => { setDay(i); setSlot(0); }} className={"flex min-h-[76px] flex-col items-center justify-center rounded-xl border px-0.5 py-2 transition-colors duration-150 disabled:cursor-not-allowed " + (on ? "border-[#0B7C70] bg-[#0B7C70] text-white" : fc === 0 ? "border-transparent bg-[#F1F5F4] text-[#6B807D]" : "border-[#CFDEDB] bg-white text-[#10302C] hover:border-[#0B7C70]")}>
                            <span className={"text-[12px] font-semibold " + (on ? "text-white" : "")}>{off === 0 ? "Today" : WD[new Date(d).getUTCDay()]}</span>
                            <span className="text-[19px] font-extrabold leading-tight tabular-nums">{new Date(d).getUTCDate()}</span>
                            <span className={"text-[11px] font-semibold tabular-nums " + (on ? "text-white" : fc === 0 ? "" : "text-[#0A6B61]")}>{fc === 0 ? "Full" : fc + " free"}</span>
                          </button>
                        );
                      })}
                    </div>

                    <h2 className="mt-7 text-[19px] font-bold">Choose a time</h2>
                    <div className="text-[14px] text-[#4A6662]">{dateLong(selDay)} · 30-minute visit</div>
                    <AnimatePresence mode="wait" initial={false}>
                      <motion.div key={selDay} initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: 0.15 }} className="mt-3 space-y-4">
                        {free.length === 0 && (
                          <div className="flex items-center gap-3 rounded-xl bg-[#F1F5F4] p-4 text-[15px] text-[#24433F]"><Calendar className="h-5 w-5 shrink-0 text-[#557370]" /> No free times this week. Try the next week.</div>
                        )}
                        {groups.filter((g) => g[1].length > 0).map(([label, ts]) => (
                          <div key={label}>
                            <div className="mb-2 flex items-center gap-1.5 text-[13px] font-semibold text-[#557370]"><Clock className="h-4 w-4" /> {label}</div>
                            <div role="radiogroup" aria-label={label + " times"} className="grid grid-cols-4 gap-2 sm:grid-cols-6">
                              {ts.map((t) => {
                                const on = slot === t;
                                return (
                                  <button key={t} role="radio" aria-checked={on} onClick={() => setSlot(t)} className={"h-11 rounded-xl border text-[15px] font-bold tabular-nums transition-colors duration-150 active:scale-[0.97] " + (on ? "border-[#0B7C70] bg-[#0B7C70] text-white" : "border-[#CFDEDB] bg-white text-[#10302C] hover:border-[#0B7C70]")}>
                                    {hm(t)}
                                  </button>
                                );
                              })}
                            </div>
                          </div>
                        ))}
                      </motion.div>
                    </AnimatePresence>

                    <h2 className="mt-7 text-[19px] font-bold">What's the visit for?</h2>
                    <div role="radiogroup" aria-label="Reason" className="mt-3 flex flex-wrap gap-2">
                      {REASONS.map((r) => {
                        const on = reason === r && !custom.trim();
                        return (
                          <button key={r} role="radio" aria-checked={on} onClick={() => { setReason(r); setCustom(""); }} className={"h-11 rounded-full border px-4 text-[14px] font-bold transition-colors duration-150 " + (on ? "border-[#0B7C70] bg-[#E6F4F1] text-[#0A6B61]" : "border-[#CFDEDB] bg-white text-[#24433F] hover:border-[#B5CCC8]")}>{r}</button>
                        );
                      })}
                    </div>
                    <label htmlFor="reason-text" className="mt-4 block text-[14px] font-bold text-[#24433F]">Or describe it <span className="font-normal text-[#557370]">(optional)</span></label>
                    <input id="reason-text" value={custom} maxLength={80} onChange={(e) => setCustom(e.target.value)} placeholder="e.g. Rash on my arm for a week" className="mt-1.5 h-12 w-full rounded-xl border border-[#CFDEDB] bg-white px-4 text-[16px] outline-none transition-[border-color,box-shadow] duration-150 placeholder:text-[#5F7B77] focus:border-[#0B7C70] focus:ring-4 focus:ring-[#12A594]/15" />

                    <AnimatePresence>
                      {err && (
                        <motion.div role="alert" initial={reduce ? false : { opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.18 }} className="mt-5 flex gap-2.5 rounded-xl bg-[#FDEEEC] px-4 py-3 text-[14px] font-semibold text-[#A1261B]"><AlertCircle className="mt-0.5 h-4 w-4 shrink-0" /> {err}</motion.div>
                      )}
                    </AnimatePresence>

                    <div className="mt-6 border-t border-[#EEF3F2] pt-5">
                      <div className="mb-3 text-[15px] text-[#24433F]" aria-live="polite">
                        {slot ? (
                          <>
                            <span className="font-bold">{rel(slot, now)}, {dateLong(slot)} at <span className="tabular-nums">{hm(slot)}</span></span>
                            <span className="text-[#4A6662]"> · {finalReason} · {s(doctor.room)}</span>
                          </>
                        ) : (
                          <span className="text-[#4A6662]">Pick a time to continue.</span>
                        )}
                      </div>
                      <button disabled={!slot || busy} onClick={() => void confirm()} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#0B7C70] text-[16px] font-bold text-white transition-colors duration-150 hover:bg-[#096A60] active:scale-[0.99] disabled:cursor-not-allowed disabled:bg-[#DCE7E5] disabled:text-[#4A6662]">
                        <Check className="h-5 w-5" /> {busy ? "Booking…" : "Confirm booking"}
                      </button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.section>
          </>
        )}
      </main>
    </div>
  );
}
